def solve(nums, k):
    # Algorithm options with their probabilities
    algorithms = [
        ('quickselect', 0.3),
        ('heap', 0.3),
        ('sort', 0.2),
        ('introselect', 0.15),
        ('merge sort', 0.05)
    ]

    # Choose an algorithm at random based on the probabilities
    selected = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if selected == 'quickselect':
        def quickselect(arr, k):
            pivot = random.choice(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]
            if k <= len(left):
                return quickselect(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return quickselect(right, k - len(left) - len(mid))
        return quickselect(nums, k)

    elif selected == 'heap':
        import heapq
        return heapq.nsmallest(k, nums)[-1]

    elif selected == 'sort':
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]

    elif selected == 'introselect':
        def introselect(arr, k):
            if len(arr) <= 12:
                return sorted(arr)[k-1]
            pivot = random.choice(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]
            if k <= len(left):
                return introselect(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return introselect(right, k - len(left) - len(mid))
        return introselect(nums, k)

    elif selected == 'merge sort':
        def merge_sort(arr):
            if len(arr) <= 1:
                return arr
            mid = len(arr) // 2
            left = merge_sort(arr[:mid])
            right = merge_sort(arr[mid:])
            return merge(left, right)

        def merge(left, right):
            result = []
            i = j = 0
            while i < len(left) and j < len(right):
                if left[i] <= right[j]:
                    result.append(left[i])
                    i += 1
                else:
                    result.append(right[j])
                    j += 1
            result.extend(left[i:])
            result.extend(right[j:])
            return result

        nums_sorted = merge_sort(nums)
        return nums_sorted[k-1]

